import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"Entenda rankings e competições","description":"","frontmatter":{"title":"Entenda rankings e competições","docId":"user.points.rankings","translationKey":"user.points.rankings","locale":"pt","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"1c45cf6e9355092d95dc9f90025b2965e0a6a4cddb453fb25680192ab41e873c","translationRevision":"08ea2808d500c768abf0721cd821a148cee5fce642749bca082492a5ae29a9ed","order":30},"headers":[],"relativePath":"pt/user/points/rankings.md","filePath":"pt/user/points/rankings.md","lastUpdated":1795727787000}`),s={name:`pt/user/points/rankings.md`};function c(a,o,s,c,l,u){let d=e(`DemoFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="understand-rankings-and-competitions" tabindex="-1">Entenda rankings e competições <a class="header-anchor" href="#understand-rankings-and-competitions" aria-label="Permalink to “Entenda rankings e competições”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objetivo e pré-requisitos”">​</a></h2><p>Escolha a visualização classificada adequada e reconheça os limites da área de rankings em desenvolvimento. Você precisa de atividade recebida para ter pontuações significativas. Comece pela classificação comum de <a href="./rules.html">Points</a> ou pelos painéis dos principais espectadores no <a href="./../live/feed.html">Live feed</a> quando precisar apenas inspecionar os espectadores atuais.</p><h2 id="use-the-right-view" tabindex="-1">Use a visualização correta <a class="header-anchor" href="#use-the-right-view" aria-label="Permalink to “Use a visualização correta”">​</a></h2><ol><li>Em <strong>Points</strong>, pesquise um espectador e ordene por pontos, nível ou identidade do espectador. Atualize antes de comparar um ajuste manual com uma atribuição.</li><li>Em <strong>Live feed</strong>, inspecione os painéis disponíveis de espectadores classificados. Eles podem receber instantâneos do mecanismo de ranking independentemente da tabela de saldos de pontos.</li><li>Para um overlay, abra <a href="./../overlays/">Overlays</a>, selecione o tipo ranking e inspecione as opções de fonte. Uma fonte de ranking configurada precisa existir antes de sua saída aparecer.</li></ol><p>A área dedicada <strong>Rankings &amp; competitions</strong> é experimental. Sua rota de frontend é <code>#/rankings</code>, mas ela está deliberadamente oculta na navegação principal e não é restaurada como aba inicial. A ausência de um item na barra lateral não significa que a rota ou o mecanismo de ranking tenha sido removido.</p><h2 id="configure-an-experimental-ranking" tabindex="-1">Configure um ranking experimental <a class="header-anchor" href="#configure-an-experimental-ranking" aria-label="Permalink to “Configure um ranking experimental”">​</a></h2><p>Se seu ambiente expuser essa área, comece com um criador, uma sala, agrupamento por usuário e uma janela de sessão. Adicione uma métrica anunciada, como <code>tiktok.like</code> / <code>like.count</code>, com peso <code>1</code>. Defina um limite modesto de resultados e crie a definição. O formulário também aceita janelas móveis e diárias, com limites explícitos de duração/eventos ou deslocamento de fuso horário.</p><p>Leia o instantâneo resultante antes de introduzir fontes adicionais. Pausar e retomar afetam a coleta do ranking; redefinir limpa intencionalmente o estado do ranking. Opções de competição e fontes relacionadas a votos têm suas próprias regras de agrupamento. Não presuma que redefinir pontos também redefina uma competição nem que todo agrupamento personalizado funcione com toda métrica.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Resultado esperado e status”">​</a></h2><p>As classificações comuns estão disponíveis; a página dedicada de gerenciamento permanece experimental. As pontuações vêm do host, não da contagem de linhas exibidas no feed. A aceitação em transmissão real/OBS e todas as combinações de competição não são comprovadas por este guia.</p><h2 id="recovery" tabindex="-1">Recuperação <a class="header-anchor" href="#recovery" aria-label="Permalink to “Recuperação”">​</a></h2><p>Confira criador, sala, ativação de fontes, janela e estado de pausa quando as pontuações continuarem vazias. Remova combinações de fonte/grupo incompatíveis em vez de inventar nomes de campos. Preserve dados importantes por meio de <a href="./../preferences/backups.html">backups</a> antes das redefinições e inclua o ID da definição e o código de diagnóstico em um relatório.</p><h2 id="operational-details" tabindex="-1">Detalhes de operação <a class="header-anchor" href="#operational-details" aria-label="Permalink to “Detalhes de operação”">​</a></h2><p>A tabela Points solicita 100 espectadores e filtra/ordena apenas essas linhas. Atualizar ou ordenar por nome não pesquisa toda a base. Os rankings do feed mostram 10 linhas por sessão de criador/sala: diamantes de presentes em Top e quantidades em Likes, acompanhando até 5.000 espectadores. Não medem pontos salvos. Confira unidades e limites da sessão antes de comparar totais.</p><p>Experimente interativamente antes de tocar na sua configuração real:</p>`,16),t(d,{scenario:`points`,locale:`pt`,panel:`points`,title:`Experimente rankings e pontos de espectadores`}),o[1]||=r(`<h2 id="command-line-operations" tabindex="-1">Operações de linha de comando <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “Operações de linha de comando”">​</a></h2><p>Cada operação deste guia também está disponível na CLI — offline, scriptável e apta para agentes. As linhas de uso são sintaxe do parser e permanecem em inglês em todos os idiomas.</p><table tabindex="0"><thead><tr><th>Comando</th><th>Resumo</th></tr></thead><tbody><tr><td><code>tiktools ranking list</code></td><td>listar as definições de ranking</td></tr><tr><td><code>tiktools ranking metrics</code></td><td>métricas disponíveis para as definições de ranking</td></tr><tr><td><code>tiktools ranking create --record &lt;json&amp;#124;@file&gt;</code></td><td>criar uma definição de ranking</td></tr><tr><td><code>tiktools ranking update --record &lt;json&amp;#124;@file&gt;</code></td><td>atualizar uma definição de ranking</td></tr><tr><td><code>tiktools ranking get &lt;id&gt;</code></td><td>ler um ranking</td></tr><tr><td><code>tiktools ranking snapshot &lt;id&gt;</code></td><td>classificação atual de um ranking</td></tr><tr><td><code>tiktools ranking delete &lt;id&gt;</code></td><td>excluir um ranking <strong>destrutivo</strong></td></tr><tr><td><code>tiktools ranking reset &lt;id&gt;</code></td><td>redefinir o estado acumulado <strong>destrutivo</strong></td></tr><tr><td><code>tiktools ranking pause &lt;id&gt;</code></td><td>pausar a acumulação</td></tr><tr><td><code>tiktools ranking resume &lt;id&gt;</code></td><td>retomar a acumulação</td></tr><tr><td><code>tiktools ranking contribute --record &lt;json&amp;#124;@file&gt;</code></td><td>adicionar uma contribuição externa</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Comando</th><th>Resumo</th></tr></thead><tbody><tr><td><code>tiktools competition list</code></td><td>listar as competições</td></tr><tr><td><code>tiktools competition get &lt;id&gt;</code></td><td>ler uma competição</td></tr><tr><td><code>tiktools competition create --record &lt;json&amp;#124;@file&gt;</code></td><td>criar uma competição</td></tr><tr><td><code>tiktools competition update --record &lt;json&amp;#124;@file&gt;</code></td><td>atualizar uma competição</td></tr><tr><td><code>tiktools competition delete &lt;id&gt;</code></td><td>excluir uma competição <strong>destrutivo</strong></td></tr><tr><td><code>tiktools competition state &lt;id&gt;</code></td><td>estado atual da competição</td></tr><tr><td><code>tiktools competition results &lt;id&gt;</code></td><td>resultados finais ou intermediários</td></tr><tr><td><code>tiktools competition action --record &lt;json&amp;#124;@file&gt;</code></td><td>registrar uma ação de competição</td></tr><tr><td><code>tiktools competition mark-action-uncertain --record &lt;json&amp;#124;@file&gt;</code></td><td>marcar uma ação como incerta</td></tr><tr><td><code>tiktools competition resolve-action --record &lt;json&amp;#124;@file&gt;</code></td><td>resolver uma ação incerta</td></tr><tr><td><code>tiktools competition start &lt;id&gt;</code></td><td>iniciar uma competição</td></tr><tr><td><code>tiktools competition finish &lt;id&gt;</code></td><td>finalizar uma competição <strong>destrutivo</strong></td></tr><tr><td><code>tiktools competition candidates &lt;id&gt;</code></td><td>candidatos a vencedor</td></tr><tr><td><code>tiktools competition select-winner --record &lt;json&amp;#124;@file&gt;</code></td><td>selecionar o vencedor</td></tr><tr><td><code>tiktools competition pause &lt;id&gt;</code></td><td>pausar uma competição</td></tr><tr><td><code>tiktools competition resume &lt;id&gt;</code></td><td>retomar uma competição</td></tr><tr><td><code>tiktools competition cancel &lt;id&gt;</code></td><td>cancelar uma competição <strong>destrutivo</strong></td></tr></tbody></table><p>Consulte a <a href="./../../developer/cli.html">referência completa de comandos</a> para as convenções, a saída JSON e os marcadores de operações destrutivas.</p>`,5)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};